<!-- Os painéis permitem avaliar as ações, sem enviar formulários nem alterar dados. -->
<dialog id="dialogo-acao" class="dialogo-acao" aria-labelledby="titulo-acao" aria-describedby="descricao-acao"><div class="topo-dialogo"><span class="selo-demonstracao" id="ambito-acao">Ação do processo</span><button type="button" class="botao-icone" data-fechar-acao aria-label="Fechar prévia"><i class="fa-solid fa-xmark" aria-hidden="true"></i></button></div><h2 id="titulo-acao"></h2><p id="descricao-acao"></p><div class="referencia-acao"><i class="fa-regular fa-file-lines" aria-hidden="true"></i><span id="referencia-acao"></span></div>
<section class="painel-acao" data-painel="adicionar" hidden><div class="escolha-origem" role="group" aria-label="Origem do documento"><button type="button" data-origem="editor" aria-pressed="true"><i class="fa-regular fa-pen-to-square" aria-hidden="true"></i>Criar no editor</button><button type="button" data-origem="upload" aria-pressed="false"><i class="fa-solid fa-arrow-up-from-bracket" aria-hidden="true"></i>Enviar arquivo</button></div><label>Título do documento<input type="text" placeholder="Ex.: Documento complementar"></label><label>Tipo de documento<select><option>Solicitação</option><option>Despacho</option><option>Parecer</option><option>Anexo</option></select></label><p id="previa-editor" class="ajuda-acao">O editor de documentos será construído na próxima etapa.</p><label id="previa-upload" hidden>Arquivo demonstrativo<input type="file" accept="application/pdf"><small>O arquivo selecionado não será enviado.</small></label></section>
<section class="painel-acao" data-painel="remover" hidden><p class="observacao-acao">O documento selecionado está indicado acima. Esta prévia não remove o documento, suas versões ou assinaturas.</p><label>Motivo da solicitação<textarea rows="3" placeholder="Descreva o motivo…"></textarea></label></section>
<section class="painel-acao" data-painel="tramitar" hidden><label>Unidade de destino<select><option>Matriz</option><option>Filial Centro</option></select></label><label>Setor de destino<select><option>Administrativo</option><option>Financeiro</option><option>Jurídico</option></select></label><label>Mensagem<textarea rows="3" placeholder="Descreva a providência esperada…"></textarea></label><p class="ajuda-acao">Destinos ilustrativos. Nenhum envio ou recebimento será registrado.</p></section>
<section class="painel-acao" data-painel="acesso" hidden><label>Nível de acesso<select id="nivel-acesso-previa"><option>Interno</option><option>Confidencial</option><option>Restrito por setor</option></select></label><p class="ajuda-acao">As autorizações específicas serão configuradas em uma próxima etapa.</p></section>
<section class="painel-acao" data-painel="assinar" hidden><div class="informacao-assinatura"><span><i class="fa-solid fa-signature" aria-hidden="true"></i></span><div><strong>Assinatura interna</strong><p>Usuário demonstrativo: <?= esc($nomeUsuario) ?></p><small id="versao-assinatura"></small></div></div><p class="ajuda-acao">Esta prévia não coleta credenciais nem produz uma assinatura.</p></section>
<section class="painel-acao" data-painel="bloco" hidden><label>Bloco de assinatura<select><option value="">Selecione um bloco demonstrativo</option><option>Assinaturas administrativas</option><option>Revisão da direção</option></select></label><p class="ajuda-acao">A inclusão se refere ao documento e à versão indicados acima.</p></section>
<section class="painel-acao" data-painel="informacoes" hidden><dl class="informacoes-processo"><div><dt>Tipo de processo</dt><dd><?= esc($processo['tipo']) ?></dd></div><div><dt>Interessado</dt><dd><?= esc($processo['interessado']) ?></dd></div><div><dt>Origem</dt><dd><?= esc($processo['unidade'] . ' / ' . $processo['setor']) ?></dd></div><div><dt>Destinos atuais</dt><dd><?= esc(implode(', ', $processo['destinos'])) ?></dd></div><div><dt>Responsável demonstrativo</dt><dd><?= esc($processo['responsavel']) ?></dd></div><div><dt>Abertura</dt><dd><?= esc(date('d/m/Y', strtotime($processo['abertura']))) ?></dd></div></dl></section>
<section class="painel-acao" data-painel="historico" hidden><ol class="historico-processo"><li><strong>Documento incluído no processo</strong><span>Documentação complementar · Exemplo de movimentação</span></li><li><strong>Processo encaminhado para análise</strong><span>Administrativo · Exemplo de tramitação</span></li><li><strong>Processo aberto</strong><span><?= esc($processo['unidade'] . ' / ' . $processo['setor']) ?> · Registro demonstrativo</span></li></ol></section>
<section class="painel-acao" data-painel="etiquetas" hidden><label>Etiquetas<input type="text" value="<?= esc($processo['etiqueta'], 'attr') ?>"></label></section>
<section class="painel-acao" data-painel="pastas" hidden><label>Pasta<select><option>Administrativo / Compras</option><option>Administrativo / Contratos</option><option>Pessoas / Admissões</option></select></label></section>
<section class="painel-acao" data-painel="padrao" hidden><p id="explicacao-acao" class="observacao-acao"></p></section>
<footer class="rodape-acao"><p><i class="fa-solid fa-circle-info" aria-hidden="true"></i>Prévia visual. Nenhuma alteração será gravada.</p><button type="button" class="btn btn-primary" data-fechar-acao>Fechar prévia</button></footer></dialog>
